files.check-config.ps1:
$v=(Get-Content -LiteralPath './config.ini' -Raw).Trim()
if($v -ne 'mode=ready'){ Write-Error 'configuration is not ready'; exit 2 }
[IO.File]::WriteAllText((Join-Path $PSScriptRoot 'config-result.txt'),'READY',[Text.UTF8Encoding]::new($false))

files.probe.ps1:
$p=Start-Process -FilePath 'pwsh.exe' -ArgumentList @('-NoProfile','-File',(Join-Path $PSScriptRoot 'worker.ps1')) -PassThru
if(-not $p.WaitForExit(200)){ $p.Kill($true); $p.WaitForExit(); Remove-Item -LiteralPath ./worker.pid -Force -ErrorAction SilentlyContinue; Write-Error 'worker exceeded 200 ms and was stopped'; exit 124 }
exit $p.ExitCode
